"""Lazy iterable transformations which compose with ordinary glom specs."""
import itertools

from boltons.iterutils import chunked_iter, unique_iter, windowed_iter
from glom.core import (T, Path, SKIP, STOP, _MISSING, TargetRegistry, glom)


class First(object):
    """Return the first item matching *key*, or *default* (None).

    The key is a glom spec; its result is tested for truth, while the
    original matching item is returned.
    """
    def __init__(self, key=T, default=None):
        self.key = key
        self.default = default

    def glomit(self, target, scope):
        for item in target:
            if scope[glom](item, self.key, scope):
                return item
        return self.default

    def __repr__(self):
        return 'First(%r, default=%r)' % (self.key, self.default)


class Iter(object):
    """Lazily apply a spec to an iterable and chain transformations.

    Use :meth:`all` to materialize the result, or :meth:`first` to select
    the first matching item. Each chain is independent of its source.
    """
    def __init__(self, subspec=T, sentinel=STOP):
        self.subspec = subspec
        self.sentinel = sentinel
        self._steps = ()

    def _chain(self, name, *args):
        ret = type(self)(self.subspec, self.sentinel)
        ret._steps = self._steps + ((name, args),)
        return ret

    def map(self, subspec=T):
        return self._chain('map', subspec)

    def filter(self, key=T):
        return self._chain('filter', key)

    def chunked(self, size, fill=_MISSING):
        return self._chain('chunked', size, fill)

    def windowed(self, size):
        return self._chain('windowed', size)

    def flatten(self):
        return self._chain('flatten')

    def unique(self, key=T):
        return self._chain('unique', key)

    def slice(self, *args):
        return self._chain('slice', *args)

    def takewhile(self, key=T):
        return self._chain('takewhile', key)

    def dropwhile(self, key=T):
        return self._chain('dropwhile', key)

    def all(self):
        return (self, list)

    def first(self, key=T, default=None):
        return (self, First(key, default))

    @staticmethod
    def _map(iterator, spec, scope, sentinel):
        for i, item in enumerate(iterator):
            value = scope[glom](item, spec,
                                scope.new_child({Path: scope[Path] + [i]}))
            if value is STOP or value is sentinel:
                break
            if value is not SKIP:
                yield value

    def glomit(self, target, scope):
        handler = scope[TargetRegistry].get_handler('iterate', target,
                                                    path=scope[Path])
        iterator = self._map(handler(target), self.subspec, scope, self.sentinel)
        for name, args in self._steps:
            if name in ('filter', 'takewhile', 'dropwhile', 'unique'):
                spec = args[0]
                def key(item, spec=spec):
                    return scope[glom](item, spec, scope)
            if name == 'map':
                iterator = self._map(iterator, args[0], scope, self.sentinel)
            elif name == 'filter':
                iterator = filter(key, iterator)
            elif name == 'chunked':
                size, fill = args
                kw = {} if fill is _MISSING else {'fill': fill}
                iterator = chunked_iter(iterator, size, **kw)
            elif name == 'windowed':
                iterator = windowed_iter(iterator, args[0])
            elif name == 'flatten':
                iterator = itertools.chain.from_iterable(iterator)
            elif name == 'unique':
                iterator = unique_iter(iterator, key=key)
            elif name == 'slice':
                iterator = itertools.islice(iterator, *args)
            elif name == 'takewhile':
                iterator = itertools.takewhile(key, iterator)
            elif name == 'dropwhile':
                iterator = itertools.dropwhile(key, iterator)
        return iterator

    def __repr__(self):
        ret = 'Iter(%r)' % (self.subspec,)
        for name, args in self._steps:
            ret += '.%s(%s)' % (name, ', '.join(repr(arg) for arg in args))
        return ret
